-- VALIDAÇÃO (consulta de resultados)
select c.name, d.stat_date, d.ad_spend_eur, d.revenue_eur, d.cogs_eur, d.profit_eur, d.roas from public.ec_v_campaign_daily d join public.ec_campaigns c on c.id=d.campaign_id order by d.stat_date,c.name;
select name,expense_type,amount_eur,first_charge_on from public.ec_expenses order by name;
